function dock(){const items=[['home','home',tr('الرئيسية','Home')],['discover','discover',tr('استكشاف','Discover')],['live','live',tr('بث مباشر','Live')],['manga','manga',tr('مانجا','Manga')],['books','books',tr('كتب','Books')],['audiobooks','audio',tr('كتب صوتية','Audio')],['anime','anime',tr('أنمي','Anime')],['music','music',tr('موسيقى','Music')],['downloads','download',tr('التنزيلات','Downloads')],['mylist','heart',tr('قائمتي','My List')]];$('#dock').innerHTML=items.map(([k,i,n])=>`<button class="dockBtn ${state.page===k?'active':''}" data-route="${k}"><span class="dockIcon">${svgIcon(i)}</span><span>${n}</span></button>`).join('');bindDynamic()}
function featureRail(){const items=[['calendar','calendar',tr('تقويم الحلقات','TV Calendar')],['quiz','spark',tr('اقتراحات ذكية','Smart Picks')],['continue','play',tr('أكمل المشاهدة','Continue')],['live','live',tr('بث مباشر','Live TV')],['audiobooks','audio',tr('كتب صوتية','Audiobooks')],['downloads','download',tr('التنزيلات','Downloads')]];return `<section class="section"><div class="sectionHead"><h2>${tr('اختصارات','Quick Access')}</h2></div><div class="featureRail">${items.map(([r,i,n])=>`<button data-route="${r}">${svgIcon(i)}<b>${n}</b></button>`).join('')}</div></section>`}
function castRow(c){return `<div class="castRow">${(c||[]).slice(0,20).map(p=>`<button class="castCard bare" data-person="${p.id}">${p.profile_path?`<img src="${IMG}w185${p.profile_path}">`:'<span class="castFallback"></span>'}<b>${esc(p.name)}</b><small>${esc(p.character||'')}</small></button>`).join('')}</div>`}
function bindDynamic(){$$('[data-detail]').forEach(e=>e.onclick=()=>route(`details/${e.dataset.detail}`));$$('[data-route]').forEach(e=>e.onclick=()=>route(e.dataset.route));$$('[data-person]').forEach(e=>e.onclick=()=>route(`person/${e.dataset.person}`));$$('[data-trailer-media]').forEach(e=>e.onclick=async()=>{const [type,id]=e.dataset.trailerMedia.split('/');await openMediaTrailer(type,id)})}
async function openMediaTrailer(type,id){try{const d=await api(`/v1/tmdb/details?type=${type}&id=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`),v=(d.videos?.results||[]).find(x=>x.site==='YouTube'&&['Trailer','Teaser'].includes(x.type));if(!v)return toast(tr('لا يوجد تريلر متاح','No trailer available'));openTrailer(v.key)}catch{toast(tr('تعذر تحميل التريلر','Trailer unavailable'))}}

function spotSlide(x,i){const type=typeOf(x),meta=[year(x),type==='tv'?tr('مسلسل','TV'):tr('فيلم','Movie'),x.vote_average?`★ ${Number(x.vote_average).toFixed(1)}`:''].filter(Boolean).join(' • ');return `<article class="spotSlide" data-spot="${i}" style="background-image:url('${backdrop(x)}')"><div class="spotCopy"><span class="spotLabel">SPOTLIGHT · ${String(i+1).padStart(2,'0')}</span><div class="spotMeta">${esc(meta)}</div><h1>${esc(title(x))}</h1><p>${esc(x.overview||'')}</p><div class="spotActions"><button class="spotBtn primary" data-detail="${type}/${x.id}">${svgIcon('info')}<span>${tr('التفاصيل','Details')}</span></button><button class="spotBtn trailer" data-trailer-media="${type}/${x.id}">${svgIcon('play')}<span>${tr('التريلر','Trailer')}</span></button></div></div></article>`}
function bindSpotlight(){const t=$('.spotlightTrack');if(!t)return;const dots=$$('.spotDots i'),counter=$('.spotCounter'),slides=$$('.spotSlide');let raf=0,current=0;const update=()=>{cancelAnimationFrame(raf);raf=requestAnimationFrame(()=>{const tr=t.getBoundingClientRect(),cx=tr.left+tr.width/2;let best=0,dist=Infinity;slides.forEach((sl,i)=>{const r=sl.getBoundingClientRect(),d=Math.abs((r.left+r.width/2)-cx);if(d<dist){dist=d;best=i}});current=best;dots.forEach((d,n)=>d.classList.toggle('active',n===current));if(counter)counter.textContent=`${String(current+1).padStart(2,'0')} / ${String(slides.length).padStart(2,'0')}`})};const go=delta=>{current=Math.max(0,Math.min(slides.length-1,current+delta));slides[current]?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});setTimeout(update,120)};t.addEventListener('scroll',update,{passive:true});$('.spotNext')?.addEventListener('click',()=>go(1));$('.spotPrev')?.addEventListener('click',()=>go(-1));dots.forEach((d,i)=>d.addEventListener('click',()=>{current=i;slides[i]?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});setTimeout(update,120)}));update()}
async function home(){state.page='home';dock();setTop(tr('الرئيسية','Home'));if(!state.home)state.home=await api(`/v1/tmdb/home?language=${state.lang==='ar'?'ar-SA':'en-US'}`);const h=state.home,spots=(h.trending||[]).filter(x=>x.media_type!=='person'&&backdrop(x)).slice(0,10);let html=`<section class="spotlight"><div class="spotlightTrack">${spots.map(spotSlide).join('')}</div><button class="spotArrow spotPrev">‹</button><button class="spotArrow spotNext">›</button><div class="spotDots">${spots.map((_,i)=>`<i class="${i===0?'active':''}"></i>`).join('')}</div><div class="spotCounter">01 / ${String(spots.length).padStart(2,'0')}</div></section>`;html+=(setting('continue',true)?continueSection():'')+section(tr('أفضل 10 هذا الأسبوع','Top 10 This Week'),(h.trending||[]).filter(x=>x.media_type!=='person').slice(0,10),true)+section(tr('أفلام رائجة','Popular Movies'),h.movies,false,'genre/movie/all')+section(tr('مسلسلات رائجة','Popular TV'),h.tv,false,'genre/tv/all')+`<section class="section"><div class="sectionHead"><h2>${tr('التصنيفات','Genres')}</h2></div><div id="genreGrid" class="genreGrid"></div></section><section class="section"><div class="sectionHead"><h2>${tr('نجوم الأسبوع','Trending Cast')}</h2></div><div id="peopleGrid" class="personGrid"></div></section>`+syncSection()+featureRail();$('#view').innerHTML=html;await fillGenres();await fillPeople();await addGenreSections();bindDynamic();bindSpotlight()}
async function fillPeople(){const d=await api(`/v1/tmdb/people?language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({results:[]}));$('#peopleGrid').innerHTML=(d.results||[]).slice(0,18).map(p=>`<button class="personCard bare" data-person="${p.id}">${p.profile_path?`<img src="${IMG}w342${p.profile_path}">`:''}<b>${esc(p.name)}</b><small>${esc((p.known_for||[]).slice(0,2).map(title).filter(Boolean).join(' · '))}</small></button>`).join('');bindDynamic()}
async function personPage(id){state.page='discover';dock();setTop(tr('الممثل','Person'));const d=(await api(`/v1/tmdb/person?id=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`)).item||{};const credits=(d.combined_credits?.cast||[]).filter(x=>x?.id&&['movie','tv'].includes(x.media_type)).sort((a,b)=>(b.popularity||0)-(a.popularity||0));const seen=new Set(),works=credits.filter(x=>!seen.has(`${x.media_type}:${x.id}`)&&seen.add(`${x.media_type}:${x.id}`)).slice(0,60);$('#view').innerHTML=`<div class="page"><div class="personPageHero">${d.profile_path?`<img src="${IMG}h632${d.profile_path}">`:''}<div><div class="eyebrow">${esc([d.known_for_department,d.birthday?String(d.birthday).slice(0,4):''].filter(Boolean).join(' • '))}</div><h1>${esc(d.name||'')}</h1><p>${esc(d.biography||tr('لا توجد نبذة متاحة.','No biography available.'))}</p></div></div><section class="knownFor"><div class="sectionHead"><h2>${tr('الأعمال','Filmography')}</h2></div><div class="mediaGrid">${row(works)}</div></section></div>`;bindDynamic()}

function trailerButton(type,id){return `<button class="secondary detailAction" data-trailer-media="${type}/${id}">${svgIcon('play')}<span>${tr('التريلر','Trailer')}</span></button>`}
async function detailPage(type,id,season=1,episode=1){state.page='detail';dock();state.type=type;state.season=Number(season)||1;state.episode=Number(episode)||1;const d=await api(`/v1/tmdb/details?type=${type}&id=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);state.detail=d;const isFav=favs().some(x=>x.type===type&&x.id==id),hasTrailer=(d.videos?.results||[]).some(v=>v.site==='YouTube'&&['Trailer','Teaser'].includes(v.type));let seasonUI='';if(type==='tv')seasonUI=`<section class="sourceLane episodeSection"><div class="sectionHead"><h2>${tr('المواسم والحلقات','Seasons & Episodes')}</h2></div><div class="seasonTabs">${(d.seasons||[]).filter(s=>s.season_number>0).map(s=>`<button class="${s.season_number===state.season?'active':''}" data-season="${s.season_number}">${tr('الموسم','Season')} ${s.season_number}</button>`).join('')}</div><div id="episodeList" class="episodeList"></div></section>`;const meta=`<section class="detailMetaGrid"><div><b>${tr('التقييم','Rating')}</b><span>${d.vote_average?Number(d.vote_average).toFixed(1):'—'}</span></div><div><b>${tr('المدة','Runtime')}</b><span>${d.runtime?d.runtime+' min':(d.episode_run_time?.[0]?d.episode_run_time[0]+' min':'—')}</span></div><div><b>${tr('التصنيفات','Genres')}</b><span>${(d.genres||[]).slice(0,3).map(g=>g.name).join(' · ')||'—'}</span></div><div><b>${tr('السنة','Year')}</b><span>${year(d)||'—'}</span></div></section>`;$('#view').innerHTML=`<section class="detailHero" style="background-image:url('${backdrop(d)}')"><div class="detailContent"><div class="eyebrow">${esc([year(d),type==='tv'?tr('مسلسل','TV'):tr('فيلم','Movie'),d.vote_average?`★ ${Number(d.vote_average).toFixed(1)}`:''].filter(Boolean).join(' • '))}</div><h1>${esc(title(d))}</h1><div class="detailActions"><button class="primary detailAction" id="watchNow">${svgIcon('play')}<span>${tr('شاهد الآن','Watch Now')}</span></button>${hasTrailer?trailerButton(type,id):''}<button class="secondary detailAction" id="favBtn">${svgIcon('heart')}<span>${isFav?tr('في قائمتي','In My List'):tr('قائمتي','My List')}</span></button></div></div></section><div class="detailBody">${meta}<p>${esc(d.overview||'')}</p><section><div class="sectionHead"><h2>${tr('طاقم التمثيل','Cast')}</h2></div>${castRow(d.credits?.cast)}</section>${seasonUI}<section class="sourceLane"><div class="sectionHead"><h2>${tr('المصادر','Sources')}</h2></div><div class="sourceStatusBar"><span class="pulse"></span><span id="sourceStatus">${tr('جاري تجهيز أفضل السيرفرات…','Preparing the best servers…')}</span></div><div id="directLane"></div><div id="totLane"></div></section>${section(tr('قد يعجبك أيضاً','You may also like'),d.recommendations?.results||d.similar?.results||[])}</div>`;bindDynamic();$('#favBtn').onclick=()=>toggleFav(type,id);if(type==='tv'){await loadEpisodes(id,state.season);$$('[data-season]').forEach(b=>b.onclick=async()=>{state.season=Number(b.dataset.season);state.episode=1;$$('[data-season]').forEach(x=>x.classList.toggle('active',x===b));await loadEpisodes(id,state.season);await loadSources(type,id)})}await loadSources(type,id);$('#watchNow').onclick=()=>{const first=$('.source');if(first)first.click();else toast(tr('لا يوجد سيرفر جاهز الآن','No ready server right now'))}}
async function loadEpisodes(id,season){const d=await api(`/v1/tmdb/season?id=${id}&season=${season}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);$('#episodeList').innerHTML=(d.episodes||[]).map(e=>`<button class="episodeCard ${e.episode_number===state.episode?'active':''}" data-episode="${e.episode_number}">${e.still_path?`<img src="${IMG}w300${e.still_path}">`:''}<div><b>${tr('الحلقة','Episode')} ${e.episode_number}: ${esc(e.name||'')}</b><small>${esc(e.air_date||'')}</small><p>${esc(e.overview||'')}</p></div></button>`).join('');$$('[data-episode]').forEach(x=>x.onclick=async()=>{state.episode=Number(x.dataset.episode);$$('[data-episode]').forEach(y=>y.classList.toggle('active',y===x));await loadSources('tv',id)})}
function sourceButton(s,i){const best=(s.qualities||[]).map(q=>q.label).filter(Boolean).sort((a,b)=>parseInt(b)-parseInt(a))[0]||'AUTO';return `<button class="source" data-i="${i}"><b>Server ${i+1}</b><small>${s.lane==='p2p'?'RWL TOT':'RWL DIRECT'}</small><div class="sourceMeta"><span>${esc(best)}</span><span class="ready">${tr('جاهز','Ready')}</span></div></button>`}
async function loadSources(type,id){const st=$('#sourceStatus');if(st)st.textContent=tr('جاري تجهيز أفضل السيرفرات…','Preparing the best servers…');let data=await api(`/v1/web/sources?${idsQuery(type,id)}`).catch(()=>({servers:[]}));let servers=data.servers||[];const cfg=jget('rwlDebrid',{});if(setting('tot',true)&&cfg?.key&&cfg?.provider){try{const t=await api(`/v1/web/torrents?${idsQuery(type,id)}`);for(const tor of (t.torrents||[]).slice(0,30)){const r=await api('/v1/web/debrid/resolve',{method:'POST',body:JSON.stringify({provider:cfg.provider,key:cfg.key,magnet:tor.magnet,filename:tor.filename,fileIndex:tor.fileIndex,season:state.season,episode:state.episode,cachedOnly:true})}).catch(()=>null);if(r?.ok&&r.url)servers.push({id:`user-${servers.length+1}`,label:`Server ${servers.length+1}`,lane:'p2p',url:r.url,qualities:[]});if(servers.length>=72)break}}catch{}}
 const seen=new Set();servers=servers.filter(s=>s?.url&&!seen.has(s.url)&&seen.add(s.url));if(!setting('direct',true))servers=servers.filter(s=>s.lane==='p2p');if(!setting('tot',true))servers=servers.filter(s=>s.lane!=='p2p');servers=servers.slice(0,72);state.servers=servers;const direct=servers.filter(s=>s.lane!=='p2p'),tot=servers.filter(s=>s.lane==='p2p');if($('#directLane'))$('#directLane').innerHTML=direct.length?`<h3>RWL DIRECT</h3><div class="sources">${direct.map((s,i)=>sourceButton(s,i)).join('')}</div>`:'';if($('#totLane'))$('#totLane').innerHTML=tot.length?`<h3>RWL TOT</h3><div class="sources">${tot.map((s,i)=>sourceButton(s,direct.length+i)).join('')}</div>`:'';if(st)st.textContent=servers.length?`${servers.length} ${tr('سيرفر جاهز','servers ready')}`:tr('لا توجد مصادر متاحة حالياً','No sources are available right now');$$('.source').forEach(b=>b.onclick=()=>playServer(servers[Number(b.dataset.i)],Number(b.dataset.i)+1,type,id))}

const LANG_INFO={ar:['🇸🇦','العربية','Arabic'],en:['🇺🇸','الإنجليزية','English'],es:['🇪🇸','الإسبانية','Spanish'],fr:['🇫🇷','الفرنسية','French'],de:['🇩🇪','الألمانية','German'],it:['🇮🇹','الإيطالية','Italian'],pt:['🇵🇹','البرتغالية','Portuguese'],ru:['🇷🇺','الروسية','Russian'],tr:['🇹🇷','التركية','Turkish'],ja:['🇯🇵','اليابانية','Japanese'],ko:['🇰🇷','الكورية','Korean'],zh:['🇨🇳','الصينية','Chinese'],hi:['🇮🇳','الهندية','Hindi'],bn:['🇧🇩','البنغالية','Bengali'],bg:['🇧🇬','البلغارية','Bulgarian'],cs:['🇨🇿','التشيكية','Czech'],pl:['🇵🇱','البولندية','Polish'],nl:['🇳🇱','الهولندية','Dutch'],sv:['🇸🇪','السويدية','Swedish'],no:['🇳🇴','النرويجية','Norwegian'],da:['🇩🇰','الدنماركية','Danish'],fi:['🇫🇮','الفنلندية','Finnish'],el:['🇬🇷','اليونانية','Greek'],he:['🇮🇱','العبرية','Hebrew'],id:['🇮🇩','الإندونيسية','Indonesian'],th:['🇹🇭','التايلاندية','Thai'],vi:['🇻🇳','الفيتنامية','Vietnamese']};
function langCode(s){let l=String(s?.lang||s?.language||'und').toLowerCase().replace('_','-').split('-')[0];const names={arabic:'ar',english:'en',spanish:'es',french:'fr',german:'de',italian:'it',portuguese:'pt',russian:'ru',turkish:'tr',japanese:'ja',korean:'ko',chinese:'zh',hindi:'hi',bengali:'bn',bulgarian:'bg',czech:'cs'};return names[l]||l||'und'}
function renderSubtitleSheet(filter=''){const list=$('#subtitleLanguageList');if(!list)return;const groups=new Map();state.subtitles.forEach((s,i)=>{const c=langCode(s);if(!groups.has(c))groups.set(c,[]);groups.get(c).push({s,i})});const pref=['ar','en'];const keys=[...groups.keys()].sort((a,b)=>{const ai=pref.indexOf(a),bi=pref.indexOf(b);if(ai>=0||bi>=0)return(ai<0?99:ai)-(bi<0?99:bi);return a.localeCompare(b)});const q=filter.trim().toLowerCase();let html=`<button class="subtitleOff ${state._activeSubtitle==null?'active':''}" data-sub-off>${tr('إيقاف الترجمة','Subtitles Off')}</button>`;for(const code of keys){const info=LANG_INFO[code]||['🌐',code.toUpperCase(),code.toUpperCase()],name=state.lang==='ar'?info[1]:info[2];if(q&&!name.toLowerCase().includes(q)&&!code.includes(q))continue;const arr=groups.get(code);html+=`<div class="languageGroup ${['ar','en'].includes(code)?'open':''}" data-lang-group="${code}"><div class="languageHead"><strong><span class="langFlag">${info[0]}</span><span>${esc(name)}</span></strong><small>${arr.length}</small></div><div class="languageTracks">${arr.map(({s,i},n)=>`<button class="subTrack ${state._activeSubtitle===i?'active':''}" data-sub-index="${i}"><span>${esc(s.name||s.label||`${name} ${n+1}`)}</span><small>CC ${String(n+1).padStart(2,'0')}</small></button>`).join('')}</div></div>`}list.innerHTML=html;$$('.languageHead').forEach(h=>h.onclick=()=>h.parentElement.classList.toggle('open'));$$('[data-sub-index]').forEach(b=>b.onclick=async()=>{await setSubtitle(Number(b.dataset.subIndex));renderSubtitleSheet($('#subtitleSearch').value);close('subtitleOverlay')});$('[data-sub-off]')?.addEventListener('click',async()=>{await setSubtitle('off');renderSubtitleSheet();close('subtitleOverlay')})}
async function applySubtitleText(text,label='Subtitle',lang='en'){const video=$('#webPlayer');[...video.querySelectorAll('track')].forEach(x=>x.remove());let vtt=String(text||'');if(!vtt.startsWith('WEBVTT'))vtt='WEBVTT\n\n'+vtt.replace(/,(\d{3})/g,'.$1');vtt=shiftVtt(vtt,Number(localStorage.getItem('rwlSubOffset')||0));const blob=URL.createObjectURL(new Blob([vtt],{type:'text/vtt'})),t=document.createElement('track');t.kind='subtitles';t.label=label;t.srclang=langCode({lang});t.src=blob;t.default=true;video.appendChild(t);setTimeout(()=>{if(t.track)t.track.mode='showing'},200)}
async function setSubtitle(v){const video=$('#webPlayer');[...video.querySelectorAll('track')].forEach(x=>x.remove());if(v==='off'){state._activeSubtitle=null;return}const i=Number(v),s=state.subtitles[i];if(!s)return;try{const txt=await fetch(s.url).then(r=>r.text());state._activeSubtitle=i;await applySubtitleText(txt,s.name||s.label||'Subtitle',s.lang||'en')}catch{toast(tr('تعذر تحميل الترجمة','Subtitle failed'))}}
function updateSubtitleOffsetLabel(){const n=Number(localStorage.getItem('rwlSubOffset')||0),txt=(n>0?'+':'')+n.toFixed(2)+'s';if($('#subSheetOffset'))$('#subSheetOffset').textContent=txt;if($('#subShiftLabel'))$('#subShiftLabel').textContent=txt}
function subtitleShift(delta){const n=Math.round((Number(localStorage.getItem('rwlSubOffset')||0)+delta)*4)/4;localStorage.setItem('rwlSubOffset',String(n));updateSubtitleOffsetLabel();const active=state._activeSubtitle;if(active!==undefined&&active!==null)setSubtitle(active);toast(`${tr('إزاحة الترجمة','Subtitle offset')}: ${(n>0?'+':'')+n.toFixed(2)}s`)}
function openSubtitleSheet(){renderSubtitleSheet();updateSubtitleOffsetLabel();open('subtitleOverlay');setTimeout(()=>$('#subtitleSearch')?.focus({preventScroll:true}),120)}

function playSvg(paused){return paused?'<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7Z"/></svg>':'<svg viewBox="0 0 24 24"><path d="M8 5v14M16 5v14"/></svg>'}
function centerSvg(paused){return paused?'<svg viewBox="0 0 64 64"><path d="M24 17 48 32 24 47Z"/></svg>':'<svg viewBox="0 0 64 64"><path d="M23 18v28M41 18v28"/></svg>'}
function showPlayerControls(){const s=$('#videoStage');if(!s)return;s.classList.remove('controlsHidden');clearTimeout(state._chromeTimer);state._chromeTimer=setTimeout(()=>{if(!$('#webPlayer').paused&&!$('#subtitleOverlay').classList.contains('open')&&!$('#floatingMenu').classList.contains('open'))s.classList.add('controlsHidden')},3200)}
function playerMenu(type){const m=$('#floatingMenu');m.innerHTML='';const add=(label,fn,active=false)=>{const b=document.createElement('button');b.textContent=label;if(active)b.classList.add('active');b.onclick=()=>{fn();m.classList.remove('open');showPlayerControls()};m.appendChild(b)};if(type==='speed'){[.5,.75,1,1.25,1.5,1.75,2].forEach(x=>add(`${x}×`,()=>{$('#webPlayer').playbackRate=x;$('#speedBtn').textContent=`${x}×`;localStorage.setItem('rwlDefaultSpeed',String(x))},Math.abs($('#webPlayer').playbackRate-x)<.01))}else if(type==='quality'){add('AUTO',()=>switchQuality(''),false);for(const q of(state.activeServer?.qualities||[]))add(q.label||'Quality',()=>switchQuality(q.url),false)}else if(type==='audio'){const tracks=$('#webPlayer').audioTracks;if(tracks&&tracks.length){for(let i=0;i<tracks.length;i++)add(tracks[i].label||tracks[i].language||`Audio ${i+1}`,()=>{for(let j=0;j<tracks.length;j++)tracks[j].enabled=j===i},tracks[i].enabled)}else add(tr('المسار الصوتي الافتراضي','Default audio track'),()=>{},true)}else if(type==='substyle'){[['classic',tr('كلاسيكي','Classic')],['large',tr('كبير','Large')],['yellow',tr('أصفر سينمائي','Cinema Yellow')]].forEach(([k,n])=>add(n,()=>{localStorage.setItem('rwlSubtitleStyle',k);applySubtitleStyle()} ,localStorage.getItem('rwlSubtitleStyle')===k))}m.classList.toggle('open');showPlayerControls()}
function switchQuality(url){const v=$('#webPlayer'),pos=v.currentTime,was=!v.paused;v.src=url||state.activeServer?.url||'';v.addEventListener('loadedmetadata',()=>{try{v.currentTime=pos}catch{}if(was)v.play().catch(()=>{})},{once:true})}
function applySubtitleStyle(){const sh=$('#playerShell');if(!sh)return;sh.classList.remove('subClassic','subLarge','subYellow');const k=localStorage.getItem('rwlSubtitleStyle')||'classic';sh.classList.add(k==='large'?'subLarge':k==='yellow'?'subYellow':'subClassic')}
function bindTapZone(el,delta){let last=0,hold=null,held=false,oldRate=1;el.onpointerdown=()=>{held=false;clearTimeout(hold);hold=setTimeout(()=>{held=true;const v=$('#webPlayer');oldRate=v.playbackRate||1;v.playbackRate=2;$('#speedIndicator').textContent='2×';showPlayerControls()},480)};const end=()=>{clearTimeout(hold);const v=$('#webPlayer');if(held){v.playbackRate=oldRate;$('#speedIndicator').textContent='';held=false;return}const now=Date.now();if(now-last<320){v.currentTime=Math.max(0,Math.min(v.duration||1e9,v.currentTime+delta));last=0}else last=now;showPlayerControls()};el.onpointerup=end;el.onpointercancel=()=>{clearTimeout(hold);if(held){$('#webPlayer').playbackRate=oldRate;$('#speedIndicator').textContent='';held=false}}}
function bindPlayer(){const v=$('#webPlayer'),stage=$('#videoStage'),seek=$('#seekBar');const sync=()=>{const paused=v.paused;$('#playPauseBtn').innerHTML=playSvg(paused);$('#centerPlay').innerHTML=centerSvg(paused);$('#timeText').textContent=`${fmt(v.currentTime)} / ${fmt(v.duration)}`;seek.value=v.duration?Math.round(v.currentTime/v.duration*1000):0;if(setting('skip',true)){$('#skipIntroBtn').classList.toggle('show',v.currentTime>10&&v.currentTime<150);$('#skipCreditsBtn').classList.toggle('show',isFinite(v.duration)&&v.duration-v.currentTime<240&&v.duration-v.currentTime>15)}if(state.detail?.id&&isFinite(v.duration)&&v.duration>120&&Math.floor(v.currentTime)%5===0)saveContinueItem({type:state.type||'movie',id:state.detail.id,title:title(state.detail),item:state.detail,season:state.season,episode:state.episode,position:v.currentTime,duration:v.duration,updated:Date.now()})};v.onplay=()=>{sync();showPlayerControls()};v.onpause=()=>{sync();showPlayerControls();stage.classList.remove('controlsHidden')};v.ontimeupdate=sync;v.onloadedmetadata=()=>{v.playbackRate=Number(localStorage.getItem('rwlDefaultSpeed')||1);$('#speedBtn').textContent=`${v.playbackRate}×`;sync();const cw=continueItems().find(x=>x.id==state.detail?.id&&x.type===(state.type||'movie')&&x.season==state.season&&x.episode==state.episode);if(cw&&cw.position>10&&cw.position<(v.duration||Infinity)-20)v.currentTime=cw.position};v.onerror=()=>{if(setting('failover',true)&&Array.isArray(state.servers)&&state.activeServerIndex+1<state.servers.length&&!state._failoverBusy){state._failoverBusy=true;const next=state.activeServerIndex+1;toast(tr('السيرفر لم يستجب — جاري الانتقال تلقائياً','Server failed — switching automatically'));setTimeout(()=>playServer(state.servers[next],next+1,state.type||'movie',state.detail?.id),450)}else toast(tr('تعذر تشغيل هذا السيرفر، جرّب سيرفر آخر','This server could not play. Try another server.'))};v.onplaying=()=>{state._failoverBusy=false;sync();showPlayerControls()};$('#playPauseBtn').onclick=$('#centerPlay').onclick=()=>v.paused?v.play().catch(()=>{}):v.pause();$('#back10Btn').onclick=()=>{v.currentTime=Math.max(0,v.currentTime-10);showPlayerControls()};$('#forward10Btn').onclick=()=>{v.currentTime=Math.min(v.duration||1e9,v.currentTime+10);showPlayerControls()};seek.oninput=()=>{if(v.duration)v.currentTime=v.duration*Number(seek.value)/1000;showPlayerControls()};$('#speedBtn').onclick=()=>playerMenu('speed');$('#qualityBtn').onclick=()=>playerMenu('quality');$('#subtitleBtn').onclick=openSubtitleSheet;$('#audioBtn').onclick=()=>playerMenu('audio');$('#airPlayBtn').onclick=()=>{if(typeof v.webkitShowPlaybackTargetPicker==='function')v.webkitShowPlaybackTargetPicker();else toast(tr('AirPlay غير متاح في هذا المتصفح','AirPlay is unavailable in this browser'))};$('#pipBtn').onclick=async()=>{try{if(document.pictureInPictureElement)await document.exitPictureInPicture();else if(document.pictureInPictureEnabled&&typeof v.requestPictureInPicture==='function')await v.requestPictureInPicture();else toast(tr('صورة داخل صورة غير متاحة هنا','Picture in Picture is unavailable here'))}catch{toast(tr('تعذر تشغيل صورة داخل صورة','Picture in Picture failed'))}};$('#fullScreenBtn').onclick=()=>stage.requestFullscreen?.()||v.webkitEnterFullscreen?.();$('#nativeFullBtn').onclick=()=>v.webkitEnterFullscreen?.();$('#skipIntroBtn').onclick=()=>v.currentTime=Math.min(v.duration||1e9,v.currentTime+85);$('#skipCreditsBtn').onclick=()=>v.currentTime=Math.max(0,(v.duration||0)-5);$('#downloadBtn').onclick=()=>{if(!state.activeServer?.url)return;saveDownload({title:$('#playerTitle').textContent,server:$('#playerServer').textContent,url:state.activeServer.url,date:Date.now()});const a=document.createElement('a');a.href=state.activeServer.url;a.target='_blank';a.download='';a.click()};$('#closePlayer').onclick=()=>{v.pause();v.removeAttribute('src');v.load();close('playerOverlay');$('#floatingMenu').classList.remove('open');close('subtitleOverlay')};stage.addEventListener('click',e=>{if(e.target===stage||e.target===v)stage.classList.contains('controlsHidden')?showPlayerControls():stage.classList.add('controlsHidden')});bindTapZone($('#tapLeft'),-10);bindTapZone($('#tapRight'),10);$('#closeSubtitleSheet').onclick=()=>close('subtitleOverlay');$('#subSheetBack').onclick=()=>subtitleShift(-.25);$('#subSheetForward').onclick=()=>subtitleShift(.25);$('#subPlayerBack').onclick=()=>v.currentTime=Math.max(0,v.currentTime-10);$('#subPlayerForward').onclick=()=>v.currentTime=Math.min(v.duration||1e9,v.currentTime+10);$('#subPlayerPlay').onclick=()=>v.paused?v.play().catch(()=>{}):v.pause();$('#subtitleSearch').oninput=e=>renderSubtitleSheet(e.target.value);$('#subtitleStyleBtn').onclick=()=>{close('subtitleOverlay');playerMenu('substyle')};$('#subtitleFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{await applySubtitleText(await f.text(),f.name,'und');state._activeSubtitle='upload';close('subtitleOverlay');toast(tr('تم تحميل ملف الترجمة','Subtitle file loaded'))}catch{toast(tr('تعذر قراءة ملف الترجمة','Could not read subtitle file'))}};applySubtitleStyle();updateSubtitleOffsetLabel();sync()}
async function playServer(s,num,type,id){state.activeServer=s;state.activeServerIndex=Math.max(0,Number(num)-1);state._failoverBusy=false;$('#playerTitle').textContent=title(state.detail);$('#playerServer').textContent=`Server ${num}`;$('#playerLane').textContent=s.lane==='p2p'?'RWL TOT':'RWL DIRECT';const v=$('#webPlayer');v.src=s.url;v.playbackRate=Number(localStorage.getItem('rwlDefaultSpeed')||1);state._activeSubtitle=null;open('playerOverlay');showPlayerControls();await loadSubtitles(type,id);v.play().catch(()=>{})}

async function mangaPage(){state.page='manga';dock();setTop(tr('مانجا','Manga'));$('#view').innerHTML=`<div class="page"><div class="pageTitleRow"><div><h1>${tr('مانجا','Manga')}</h1><p>${tr('مكتبة مانجا كاملة مع فصول وقارئ داخل RWL','A full manga library with chapters and an in-site reader')}</p></div></div><input id="mangaSearch" class="searchInput" placeholder="${tr('ابحث عن مانجا…','Search manga…')}"><div id="mangaGrid" class="mediaGrid"><div class="empty">${tr('جاري التحميل…','Loading…')}</div></div></div>`;const load=async q=>{const d=await api(`/v1/web/manga?mode=search&query=${encodeURIComponent(q||'')}`).catch(()=>({items:[]}));$('#mangaGrid').innerHTML=(d.items||[]).map(x=>`<article class="posterCard" data-route="manga-details/${x.id}">${x.cover?`<img class="mangaCardImg" src="${esc(x.cover)}" loading="lazy">`:''}<div class="posterShade"></div><div class="posterCopy"><b>${esc(x.title)}</b><small>${esc((x.tags||[]).slice(0,2).join(' • '))}</small></div></article>`).join('')||`<div class="empty">${tr('تعذر تحميل المانجا الآن','Manga is unavailable right now')}</div>`;bindDynamic()};await load('');let tm;$('#mangaSearch').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>load(e.target.value),350)}}
async function mangaDetails(id){state.page='manga';dock();const [d,ch]=await Promise.all([api(`/v1/web/manga?mode=details&id=${encodeURIComponent(id)}`),api(`/v1/web/manga?mode=chapters&id=${encodeURIComponent(id)}`)]);const m=d.item||{},chapters=(ch.chapters||[]).sort((a,b)=>{const al=a.language==='ar'?0:a.language==='en'?1:2,bl=b.language==='ar'?0:b.language==='en'?1:2;return al-bl||Number(b.chapter||0)-Number(a.chapter||0)});$('#view').innerHTML=`<div class="page mangaDetail"><div class="bookHero">${m.cover?`<img src="${esc(m.cover)}">`:''}<div><h1>${esc(m.title||'Manga')}</h1><p>${esc(m.description||'')}</p><div class="chips">${(m.tags||[]).slice(0,10).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></div><div class="sectionHead"><h2>${tr('الفصول','Chapters')}</h2><span>${chapters.length}</span></div><div class="chapterList">${chapters.map(x=>`<button data-route="manga-reader/${x.id}"><b>${tr('الفصل','Chapter')} ${esc(x.chapter||'?')} ${esc(x.title||'')}</b><small>${esc(x.language||'')}</small></button>`).join('')||`<div class="empty">${tr('لا توجد فصول متاحة','No chapters available')}</div>`}</div></div>`;bindDynamic()}

function settings(){const cfg=jget('rwlDebrid',{provider:'torbox',key:''}),sync=jget('rwlSync',{}),theme=localStorage.getItem('rwlTheme')||'cyan';$('#settingsContent').innerHTML=`
<section class="settingsGroup"><h3>${tr('المظهر','Appearance')}</h3><div class="settingRow"><div><b>${tr('اللغة','Language')}</b><small>${tr('تتغير الواجهة والوصف حسب اختيارك','Interface and descriptions follow your choice')}</small></div><div class="segmented" id="langSegment"><button data-lang="ar" class="${state.lang==='ar'?'active':''}">العربية</button><button data-lang="en" class="${state.lang==='en'?'active':''}">English</button></div></div><div class="settingRow"><div><b>${tr('لون الواجهة','Accent')}</b></div><div class="themePicker">${Object.entries(themes).map(([k,v])=>`<button class="themeDot ${theme===k?'active':''}" data-theme="${k}" style="background:${v[0]}"></button>`).join('')}</div></div>${toggleRow('glassToggle','Liquid Glass',setting('glass',true))}</section>
<section class="settingsGroup"><h3>${tr('المشغل','Player')}</h3><div class="settingRow"><div><b>${tr('سرعة التشغيل الافتراضية','Default speed')}</b></div><select id="defaultSpeed">${[.5,.75,1,1.25,1.5,1.75,2].map(x=>`<option value="${x}">${x}×</option>`).join('')}</select></div>${toggleRow('skipToggle',tr('تخطي المقدمة والنهاية','Skip intro & credits'),setting('skip',true))}${toggleRow('failoverToggle',tr('تبديل السيرفر تلقائياً عند الفشل','Auto-switch failed servers'),setting('failover',true))}${toggleRow('directToggle','RWL DIRECT',setting('direct',true))}${toggleRow('totToggle','RWL TOT',setting('tot',true))}</section>
<section class="settingsGroup"><h3>${tr('الترجمة','Subtitles')}</h3><div class="settingRow"><div><b>${tr('اللغة المفضلة','Preferred language')}</b><small>${tr('تُختار تلقائياً عند توفرها','Selected automatically when available')}</small></div><select id="subtitleLang"><option value="ar">العربية</option><option value="en">English</option><option value="off">${tr('بدون تشغيل تلقائي','Do not auto-enable')}</option></select></div><div class="settingRow"><div><b>${tr('نمط الترجمة','Subtitle style')}</b><small>${tr('يمكن تغييره أيضاً من المشغل','Also available from the player')}</small></div><select id="subtitleStyle"><option value="classic">${tr('كلاسيكي','Classic')}</option><option value="large">${tr('كبير','Large')}</option><option value="yellow">${tr('أصفر سينمائي','Cinema Yellow')}</option></select></div><div class="settingRow"><div><b>${tr('مزامنة الترجمة','Subtitle timing')}</b></div><span id="settingsSubOffset">${Number(localStorage.getItem('rwlSubOffset')||0).toFixed(2)}s</span></div></section>
<section class="settingsGroup"><h3>${tr('Debrid','Debrid')}</h3><div class="settingRow"><div><b>${tr('الخدمة','Service')}</b></div><select id="debridProvider"><option value="torbox">TorBox</option><option value="realdebrid">Real-Debrid</option><option value="alldebrid">AllDebrid</option><option value="premiumize">Premiumize</option><option value="debridlink">Debrid-Link</option></select></div><div class="settingRow"><div><b>API Key</b><small>${tr('محفوظ محلياً على جهازك','Stored locally on your device')}</small></div><input id="debridKey" type="password" value="${esc(cfg.key||'')}" autocomplete="off"></div><div class="settingRow"><button id="saveDebrid" class="primary">${tr('حفظ','Save')}</button></div></section>
<section class="settingsGroup"><h3>${tr('المزامنة','Sync')}</h3><div class="settingRow"><div><b>Trakt</b></div><input id="traktClient" placeholder="Client ID" value="${esc(sync.traktClient||'')}"><input id="traktToken" type="password" placeholder="Access Token" value="${esc(sync.traktToken||'')}"></div><div class="settingRow"><div><b>Simkl</b></div><input id="simklClient" placeholder="Client ID" value="${esc(sync.simklClient||'')}"><input id="simklToken" type="password" placeholder="Access Token" value="${esc(sync.simklToken||'')}"></div><div class="settingRow"><button id="saveSync" class="secondary">${tr('حفظ','Save')}</button><button id="pullTrakt" class="secondary">Trakt Sync</button><button id="pullSimkl" class="secondary">Simkl Sync</button></div></section>
<section class="settingsGroup"><h3>${tr('البيانات','Data')}</h3><div class="settingRow"><button id="exportCfg" class="secondary">${tr('نسخة احتياطية','Backup')}</button><label class="secondary fileBtn">${tr('استعادة','Restore')}<input id="importCfg" type="file" accept="application/json" hidden></label></div><div class="settingRow"><button id="clearData" class="secondary">${tr('مسح بيانات الموقع','Clear local data')}</button></div></section>`;
 $('#defaultSpeed').value=localStorage.getItem('rwlDefaultSpeed')||'1';$('#debridProvider').value=cfg.provider||'torbox';$('#subtitleStyle').value=localStorage.getItem('rwlSubtitleStyle')||'classic';$('#subtitleLang').value=localStorage.getItem('rwlSubtitleLang')||'ar';$$('[data-lang]').forEach(b=>b.onclick=()=>{localStorage.setItem('rwlLang',b.dataset.lang);state.lang=b.dataset.lang;location.reload()});$$('[data-theme]').forEach(b=>b.onclick=()=>{applyTheme(b.dataset.theme);$$('[data-theme]').forEach(x=>x.classList.toggle('active',x===b))});$('#glassToggle').onchange=e=>{setSetting('glass',e.target.checked);document.body.classList.toggle('noGlass',!e.target.checked)};$('#skipToggle').onchange=e=>setSetting('skip',e.target.checked);$('#failoverToggle').onchange=e=>setSetting('failover',e.target.checked);$('#directToggle').onchange=e=>setSetting('direct',e.target.checked);$('#totToggle').onchange=e=>setSetting('tot',e.target.checked);$('#defaultSpeed').onchange=e=>localStorage.setItem('rwlDefaultSpeed',e.target.value);$('#subtitleStyle').onchange=e=>{localStorage.setItem('rwlSubtitleStyle',e.target.value);applySubtitleStyle()};$('#subtitleLang').onchange=e=>localStorage.setItem('rwlSubtitleLang',e.target.value);$('#saveDebrid').onclick=()=>{jset('rwlDebrid',{provider:$('#debridProvider').value,key:$('#debridKey').value.trim()});toast(tr('تم الحفظ','Saved'))};$('#saveSync').onclick=()=>{jset('rwlSync',{traktClient:$('#traktClient').value.trim(),traktToken:$('#traktToken').value.trim(),simklClient:$('#simklClient').value.trim(),simklToken:$('#simklToken').value.trim()});toast(tr('تم الحفظ','Saved'))};$('#pullTrakt').onclick=async()=>{$('#saveSync').click();await pullSync('trakt')};$('#pullSimkl').onclick=async()=>{$('#saveSync').click();await pullSync('simkl')};$('#exportCfg').onclick=()=>{const keys=['rwlLang','rwlTheme','rwlPrefs','rwlDebrid','rwlSync','rwlFavs','rwlContinue','rwlIptvChannels','rwlBooks','rwlSubtitleStyle','rwlSubtitleLang','rwlSubOffset','rwlDefaultSpeed'];const obj={version:V8};for(const k of keys)obj[k]=localStorage.getItem(k);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download='RWL-Movies-backup.json';a.click()};$('#importCfg').onchange=async e=>{try{const o=JSON.parse(await e.target.files[0].text());for(const[k,v]of Object.entries(o))if(k!=='version'&&typeof v==='string')localStorage.setItem(k,v);location.reload()}catch{toast(tr('ملف غير صالح','Invalid file'))}};$('#clearData').onclick=()=>{if(confirm(tr('مسح جميع بيانات الموقع؟','Clear all local data?'))){localStorage.clear();location.reload()}};open('settingsOverlay')}


async function search(q){
  q=String(q||'').trim();
  if(!q){$('#searchGrid').innerHTML='';return}
  try{
    const d=await api(`/v1/tmdb/search?query=${encodeURIComponent(q)}&language=${state.lang==='ar'?'ar-SA':'en-US'}`),all=d.results||[];
    const people=all.filter(x=>x.media_type==='person').slice(0,12),media=all.filter(x=>x.media_type!=='person').slice(0,48);
    let html='';
    if(media.length) html+=`<h3 class="searchSectionTitle">${tr('أفلام ومسلسلات','Movies & TV')}</h3>${row(media)}`;
    if(people.length) html+=`<h3 class="searchSectionTitle">${tr('أشخاص','People')}</h3>${people.map(p=>`<button class="searchPersonCard bare" data-person="${p.id}">${p.profile_path?`<img src="${IMG}w342${p.profile_path}">`:''}<b>${esc(p.name||'')}</b><small>${esc((p.known_for||[]).slice(0,2).map(title).filter(Boolean).join(' · '))}</small></button>`).join('')}`;
    $('#searchGrid').innerHTML=html||`<div class="empty">${tr('لا توجد نتائج','No results')}</div>`;bindDynamic();
  }catch{$('#searchGrid').innerHTML=`<div class="empty">${tr('تعذر البحث الآن','Search is unavailable right now')}</div>`}
}

async function renderRoute(){applyTheme();document.body.classList.toggle('noGlass',!setting('glass',true));document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';const r=parseRoute().split('/');window.scrollTo(0,0);try{if(r[0]==='home')await home();else if(r[0]==='discover')await discover(r[1]||'all');else if(r[0]==='genre')await genrePage(r[1]||'movie',r[2]||'all');else if(r[0]==='details')await detailPage(r[1],r[2],r[3]||1,r[4]||1);else if(r[0]==='person')await personPage(r[1]);else if(r[0]==='manga')await mangaPage();else if(r[0]==='manga-details')await mangaDetails(r[1]);else if(r[0]==='manga-reader')await mangaReader(r[1]);else if(r[0]==='anime')await aniV6('anime');else if(r[0]==='books')await books();else if(r[0]==='audiobooks')await audiobooksPage();else if(r[0]==='music')await music();else if(r[0]==='live')livePage();else if(r[0]==='calendar')await calendarPage();else if(r[0]==='quiz')await quizPage();else if(r[0]==='continue')continuePage();else if(r[0]==='downloads')downloadsPage();else if(r[0]==='mylist')mylist();else await home()}catch(e){console.error(e);$('#view').innerHTML=`<div class="page"><h1>RWL Movies</h1><div class="empty">${esc(e.message)}</div><div class="actions"><button class="primary" onclick="location.reload()">${tr('إعادة المحاولة','Retry')}</button></div></div>`}bindDynamic()}
function init(){bindPlayer();bindGlobalPlayerKeys();$('#settingsBtn').onclick=settings;$('#searchBtn').onclick=()=>open('searchOverlay');let st;$('#searchInput').oninput=e=>{clearTimeout(st);st=setTimeout(()=>search(e.target.value),260)};$$('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));window.addEventListener('hashchange',renderRoute);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});renderRoute()}

// ===== RWL Movies Web v9 — Premium Redesign =====
const RWL_WEB_VERSION='9.0';
const themePresetsV9={
  oled:{nameAr:'OLED أسود',nameEn:'OLED Black',primary:'#f4b63f',accent:'#ffd56d',bg:'#020203',card:'#0b0b0e',top:'#09090c',glass:'rgba(8,8,11,.72)',text:'#fbfbfd',muted:'#9a9aa5'},
  cinema:{nameAr:'سينما ذهبي',nameEn:'Cinema Gold',primary:'#d99a26',accent:'#ffd76f',bg:'#090704',card:'#151007',top:'#100c06',glass:'rgba(16,12,7,.76)',text:'#fffaf0',muted:'#a89e8c'},
  midnight:{nameAr:'منتصف الليل',nameEn:'Midnight',primary:'#5a7cff',accent:'#8fa4ff',bg:'#050711',card:'#0d1222',top:'#090d19',glass:'rgba(8,12,24,.76)',text:'#f7f9ff',muted:'#9099b2'},
  aurora:{nameAr:'أورورا',nameEn:'Aurora',primary:'#13d6a2',accent:'#67f3cf',bg:'#03100d',card:'#0a1b17',top:'#071510',glass:'rgba(5,20,16,.75)',text:'#f3fffb',muted:'#8eaaa1'},
  crimson:{nameAr:'كريمسون',nameEn:'Crimson',primary:'#f02e48',accent:'#ff7387',bg:'#0d0406',card:'#1b0a0e',top:'#14070a',glass:'rgba(20,7,10,.76)',text:'#fff7f8',muted:'#ad9298'},
  glass:{nameAr:'زجاجي',nameEn:'Liquid Glass',primary:'#e6efff',accent:'#9bc6ff',bg:'#070a10',card:'#101620',top:'#0d121a',glass:'rgba(14,20,29,.60)',text:'#fbfdff',muted:'#9aa7b6'},
  light:{nameAr:'فاتح',nameEn:'Light',primary:'#131722',accent:'#3e67ff',bg:'#f3f4f7',card:'#ffffff',top:'#ffffff',glass:'rgba(255,255,255,.76)',text:'#11131a',muted:'#6f7480'}
};
function applyTheme(k){k=k||localStorage.getItem('rwlThemeV9')||localStorage.getItem('rwlTheme')||'cinema';if(!themePresetsV9[k])k='cinema';localStorage.setItem('rwlThemeV9',k);const t=themePresetsV9[k],r=document.documentElement.style;r.setProperty('--primary',t.primary);r.setProperty('--accent',t.accent);r.setProperty('--bg',t.bg);r.setProperty('--card',t.card);r.setProperty('--top',t.top);r.setProperty('--glass',t.glass);r.setProperty('--text',t.text);r.setProperty('--muted',t.muted);document.body?.setAttribute('data-theme',k);const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=t.bg}
function premiumSvg(name){const m={
  movie:'<path d="M4 6h16v12H4z"/><path d="m8 3 2 3M14 3l2 3M4 10h16"/>',tv:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m9 2 3 3 3-3"/>',
  server:'<rect x="4" y="4" width="16" height="6" rx="2"/><rect x="4" y="14" width="16" height="6" rx="2"/><path d="M8 7h.01M8 17h.01"/>',
  cloud:'<path d="M7 18h10a4 4 0 0 0 .5-8 6 6 0 0 0-11-1A4.5 4.5 0 0 0 7 18Z"/>',
  bolt:'<path d="m13 2-8 12h7l-1 8 8-12h-7l1-8Z"/>',
  star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1-5.4-2.9-5.4 2.9 1-6.1-4.4-4.3 6.1-.9L12 3Z"/>',
  play:'<path d="M8 5v14l11-7Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1-1.1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.6 1-1a5.5 5.5 0 0 0 0-7.8Z"/>',
  trailer:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m10 9 5 3-5 3Z"/>',chev:'<path d="m9 18 6-6-6-6"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>',
  language:'<path d="M4 5h10M9 3v2m-3 0c0 4 3 7 7 8M12 5c0 4-3 7-7 8"/><path d="m14 21 4-10 4 10m-6.5-4h5"/>',speed:'<path d="M5 16a7 7 0 1 1 14 0"/><path d="m12 16 4-5"/>',quality:'<path d="M4 6h16v12H4z"/><path d="M8 10h8M8 14h5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${m[name]||m.star}</svg>`}
function card(x,rank=''){const type=typeOf(x),p=poster(x,'w500'),t=title(x),rating=x.vote_average?Number(x.vote_average).toFixed(1):'';return `<article class="posterCard premiumCard" data-detail="${type}/${x.id}">${p?`<img src="${p}" loading="lazy" alt="${esc(t)}">`:'<div class="posterFallback">RWL</div>'}<div class="posterShade"></div>${rank?`<span class="rankNum">${rank}</span>`:''}${rating?`<span class="ratingBadge">★ ${rating}</span>`:''}<div class="posterCopy"><b>${esc(t)}</b><small>${esc([year(x),type==='tv'?tr('مسلسل','TV'):tr('فيلم','Movie')].filter(Boolean).join(' • '))}</small></div><button class="posterPlay" aria-label="Play">${premiumSvg('play')}</button></article>`}
function section(name,items,top10=false,more=''){return `<section class="section premiumSection"><div class="sectionHead"><div><span class="sectionKicker">RWL CURATED</span><h2>${esc(name)}</h2></div>${more?`<button class="seeAll" data-route="${more}">${tr('عرض الكل','See all')} ${premiumSvg('chev')}</button>`:''}</div><div class="horizontal ${top10?'top10Rail':''}">${row(items,top10)}</div></section>`}
function castRow(c){return `<div class="castRow premiumCast">${(c||[]).slice(0,22).map(p=>`<button class="castCard bare" data-person="${p.id}">${p.profile_path?`<img src="${IMG}w185${p.profile_path}" alt="${esc(p.name)}">`:`<span class="castFallback">${esc((p.name||'?')[0])}</span>`}<b>${esc(p.name)}</b><small>${esc(p.character||p.known_for_department||'')}</small></button>`).join('')}</div>`}
function navItemV9(routeName,label,icon){return `<button class="navPill ${state.page===routeName?'active':''}" data-route="${routeName}">${svgIcon(icon)}<span>${label}</span></button>`}
function dock(){const mobile=[['home','home',tr('الرئيسية','Home')],['discover','discover',tr('استكشاف','Discover')],['live','live',tr('مباشر','Live')],['manga','manga',tr('مانجا','Manga')],['books','books',tr('مكتبة','Library')],['mylist','heart',tr('قائمتي','My List')]];$('#dock').innerHTML=mobile.map(([k,i,n])=>`<button class="dockBtn ${state.page===k?'active':''}" data-route="${k}"><span class="dockIcon">${svgIcon(i)}</span><span>${n}</span></button>`).join('');const dn=$('#desktopNav');if(dn)dn.innerHTML=[['home','home',tr('الرئيسية','Home')],['discover','discover',tr('أفلام ومسلسلات','Movies & TV')],['anime','anime',tr('أنمي','Anime')],['manga','manga',tr('مانجا','Manga')],['live','live',tr('بث مباشر','Live')],['books','books',tr('مكتبة','Library')]].map(([k,i,n])=>navItemV9(k,n,i)).join('');bindDynamic()}
function spotlightSlideV9(x,i,total){const type=typeOf(x),rating=x.vote_average?Number(x.vote_average).toFixed(1):'';return `<article class="spotSlide premiumSpot" data-spot="${i}" style="background-image:url('${backdrop(x)}')"><div class="spotVignette"></div><div class="spotCopy"><div class="spotTopline"><span class="spotLabel">SPOTLIGHT</span><span class="spotIndex">${String(i+1).padStart(2,'0')} / ${String(total).padStart(2,'0')}</span></div><div class="spotMeta"><span>${year(x)||''}</span><span>${type==='tv'?tr('مسلسل','TV Series'):tr('فيلم','Movie')}</span>${rating?`<span class="ratingMeta">★ ${rating}</span>`:''}</div><h1>${esc(title(x))}</h1><p>${esc(x.overview||'')}</p><div class="spotActions"><button class="spotBtn primary" data-detail="${type}/${x.id}">${premiumSvg('info')}<span>${tr('التفاصيل','Details')}</span></button><button class="spotBtn trailer" data-trailer-media="${type}/${x.id}">${premiumSvg('trailer')}<span>${tr('شاهد التريلر','Watch Trailer')}</span></button></div></div></article>`}
function categoryShelfV9(){const cats=[[28,'⚡',tr('أكشن','Action')],[35,'☺',tr('كوميدي','Comedy')],[10749,'♡',tr('رومانسي','Romance')],[27,'◉',tr('رعب','Horror')],[878,'✦',tr('خيال علمي','Sci‑Fi')],[16,'✺',tr('أنيميشن','Animation')],[80,'◆',tr('جريمة','Crime')],[18,'◇',tr('دراما','Drama')]];return `<section class="section premiumSection"><div class="sectionHead"><div><span class="sectionKicker">EXPLORE</span><h2>${tr('اختر مزاجك','Browse by mood')}</h2></div></div><div class="categoryShelf">${cats.map(([id,ic,n])=>`<button data-route="genre/movie/${id}" class="categoryTile"><span>${ic}</span><b>${n}</b><small>${tr('استكشف الآن','Explore')}</small></button>`).join('')}</div></section>`}
function quickAccessV9(){const items=[['continue','play',tr('أكمل المشاهدة','Continue Watching'),tr('ارجع من نفس اللحظة','Resume where you left off')],['calendar','calendar',tr('تقويم الحلقات','TV Calendar'),tr('الحلقات القادمة','Upcoming episodes')],['quiz','spark',tr('اختيارات لك','Smart Picks'),tr('اقتراحات حسب ذوقك','Personal recommendations')],['audiobooks','audio',tr('كتب صوتية','Audiobooks'),tr('استمع أثناء التنقل','Listen anywhere')],['downloads','download',tr('التنزيلات','Downloads'),tr('الوصول السريع','Quick access')]];return `<section class="section premiumSection"><div class="sectionHead"><div><span class="sectionKicker">YOUR RWL</span><h2>${tr('أكثر من مشاهدة','More than streaming')}</h2></div></div><div class="experienceGrid">${items.map(([r,i,n,s])=>`<button data-route="${r}" class="experienceCard"><span class="experienceIcon">${svgIcon(i)}</span><span><b>${n}</b><small>${s}</small></span>${premiumSvg('chev')}</button>`).join('')}</div></section>`}
async function home(){state.page='home';dock();setTop(tr('الرئيسية','Home'));if(!state.home)state.home=await api(`/v1/tmdb/home?language=${state.lang==='ar'?'ar-SA':'en-US'}`);const h=state.home,spots=(h.trending||[]).filter(x=>x.media_type!=='person'&&backdrop(x)).slice(0,10);let html=`<section class="spotlight premiumSpotlight"><div class="spotlightTrack">${spots.map((x,i)=>spotlightSlideV9(x,i,spots.length)).join('')}</div><button class="spotArrow spotPrev" aria-label="Previous">‹</button><button class="spotArrow spotNext" aria-label="Next">›</button><div class="spotDots">${spots.map((_,i)=>`<i class="${i===0?'active':''}"></i>`).join('')}</div></section>`;if(setting('continue',true))html+=continueSection();html+=section(tr('أفضل 10 هذا الأسبوع','Top 10 This Week'),(h.trending||[]).filter(x=>x.media_type!=='person').slice(0,10),true);html+=categoryShelfV9();html+=section(tr('أفلام تشعل الحديث','Trending Movies'),h.movies,false,'genre/movie/all');html+=section(tr('مسلسلات تستحق المتابعة','Binge-worthy TV'),h.tv,false,'genre/tv/all');html+=`<section class="section premiumSection"><div class="sectionHead"><div><span class="sectionKicker">PEOPLE</span><h2>${tr('نجوم الأسبوع','Trending Cast')}</h2></div><button class="seeAll" data-route="discover/person">${tr('استكشف','Explore')} ${premiumSvg('chev')}</button></div><div id="peopleGrid" class="personGrid premiumPeople"></div></section>`;html+=quickAccessV9();$('#view').innerHTML=html;await fillPeople();await addGenreSectionsV9();bindDynamic();bindSpotlight()}
async function addGenreSectionsV9(){const sections=[[35,tr('خفيف ومضحك','Comedy')],[10749,tr('رومانسية','Romance')],[27,tr('رعب وتشويق','Horror')],[28,tr('أكشن','Action')],[878,tr('خيال علمي','Sci‑Fi')]];for(const [id,label] of sections){const d=await api(`/v1/tmdb/discover?type=movie&genre=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>null);if(d?.results?.length)$('#view').insertAdjacentHTML('beforeend',section(label,d.results,false,`genre/movie/${id}`))}bindDynamic()}
async function fillPeople(){const d=await api(`/v1/tmdb/people?language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({results:[]}));const el=$('#peopleGrid');if(!el)return;el.innerHTML=(d.results||[]).slice(0,20).map(p=>`<button class="personCard bare" data-person="${p.id}">${p.profile_path?`<img src="${IMG}w342${p.profile_path}" alt="${esc(p.name)}">`:`<span class="castFallback">${esc((p.name||'?')[0])}</span>`}<b>${esc(p.name)}</b><small>${esc((p.known_for||[]).slice(0,2).map(title).filter(Boolean).join(' · '))}</small></button>`).join('');bindDynamic()}
async function discover(type='all'){state.page='discover';dock();setTop(tr('استكشاف','Discover'));const mode=['movie','tv'].includes(type)?type:'all';const [d,genres]=await Promise.all([api(`/v1/tmdb/trending?type=${mode}&window=week&language=${state.lang==='ar'?'ar-SA':'en-US'}`),api(`/v1/tmdb/genres?type=movie&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({genres:[]}))]);$('#view').innerHTML=`<div class="page browsePage"><div class="pageHeroTitle"><span class="sectionKicker">DISCOVER</span><h1>${tr('اختَر ما يناسب مزاجك','Find your next obsession')}</h1><p>${tr('تصفح الأفلام والمسلسلات والتصنيفات بدون ضوضاء.','Browse movies, TV and genres with a clean cinematic layout.')}</p></div><div class="browseTabs"><button class="${mode==='all'?'active':''}" data-route="discover/all">${tr('الكل','All')}</button><button class="${mode==='movie'?'active':''}" data-route="discover/movie">${tr('أفلام','Movies')}</button><button class="${mode==='tv'?'active':''}" data-route="discover/tv">${tr('مسلسلات','TV')}</button></div><div class="genreChips">${(genres.genres||[]).slice(0,14).map(g=>`<button data-route="genre/movie/${g.id}">${esc(g.name)}</button>`).join('')}</div><div class="mediaGrid premiumMediaGrid">${row(d.results)}</div></div>`;bindDynamic()}
async function genrePage(type,id){state.page='discover';dock();const [d,gs]=await Promise.all([api(`/v1/tmdb/discover?type=${type}&genre=${id==='all'?'':id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`),api(`/v1/tmdb/genres?type=${type}&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({genres:[]}))]);const n=(gs.genres||[]).find(x=>String(x.id)===String(id))?.name||tr('كل المحتوى','All content');$('#view').innerHTML=`<div class="page browsePage"><div class="pageHeroTitle"><span class="sectionKicker">RWL COLLECTION</span><h1>${esc(n)}</h1><p>${tr('مختارات مرتبة لهذا التصنيف.','Curated titles for this genre.')}</p></div><div class="mediaGrid premiumMediaGrid">${row(d.results)}</div></div>`;bindDynamic()}
async function personPage(id){state.page='discover';dock();setTop(tr('الممثل','Person'));const d=(await api(`/v1/tmdb/person?id=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`)).item||{};const credits=(d.combined_credits?.cast||[]).filter(x=>x?.id&&['movie','tv'].includes(x.media_type)).sort((a,b)=>(b.popularity||0)-(a.popularity||0));const seen=new Set(),works=credits.filter(x=>!seen.has(`${x.media_type}:${x.id}`)&&seen.add(`${x.media_type}:${x.id}`)).slice(0,80);$('#view').innerHTML=`<div class="page personPremium"><section class="personPageHero">${d.profile_path?`<img src="${IMG}h632${d.profile_path}" alt="${esc(d.name)}">`:''}<div><span class="sectionKicker">CAST PROFILE</span><h1>${esc(d.name||'')}</h1><div class="personMeta">${[d.known_for_department,d.place_of_birth,d.birthday].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div><p>${esc(d.biography||tr('لا توجد نبذة متاحة.','No biography available.'))}</p></div></section><section class="premiumSection"><div class="sectionHead"><div><span class="sectionKicker">FILMOGRAPHY</span><h2>${tr('أبرز الأعمال','Popular works')}</h2></div></div><div class="mediaGrid premiumMediaGrid">${row(works)}</div></section></div>`;bindDynamic()}
function detailStatsV9(d,type){const runtime=d.runtime?`${d.runtime} ${tr('د','min')}`:(d.episode_run_time?.[0]?`${d.episode_run_time[0]} ${tr('د','min')}`:'');return `<div class="detailStats"><span>★ ${d.vote_average?Number(d.vote_average).toFixed(1):'—'}</span>${year(d)?`<span>${year(d)}</span>`:''}${runtime?`<span>${runtime}</span>`:''}<span>${type==='tv'?tr('مسلسل','TV Series'):tr('فيلم','Movie')}</span></div>`}
async function detailPage(type,id,season=1,episode=1){state.page='detail';dock();state.type=type;state.season=Number(season)||1;state.episode=Number(episode)||1;const d=await api(`/v1/tmdb/details?type=${type}&id=${id}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);state.detail=d;const isFav=favs().some(x=>x.type===type&&x.id==id),hasTrailer=(d.videos?.results||[]).some(v=>v.site==='YouTube'&&['Trailer','Teaser'].includes(v.type));const genres=(d.genres||[]).slice(0,5);let seasonUI='';if(type==='tv')seasonUI=`<section class="detailPanel episodeSection"><div class="panelTitle"><div><span class="sectionKicker">EPISODES</span><h2>${tr('المواسم والحلقات','Seasons & Episodes')}</h2></div></div><div class="seasonTabs premiumTabs">${(d.seasons||[]).filter(s=>s.season_number>0).map(s=>`<button class="${s.season_number===state.season?'active':''}" data-season="${s.season_number}">${tr('الموسم','Season')} ${s.season_number}</button>`).join('')}</div><div id="episodeList" class="episodeList premiumEpisodes"></div></section>`;$('#view').innerHTML=`<section class="detailCinema" style="--detail-bg:url('${backdrop(d)}')"><div class="detailBackdrop"></div><div class="detailCinemaInner">${poster(d)?`<img class="detailPoster" src="${poster(d,'w500')}" alt="${esc(title(d))}">`:''}<div class="detailMain"><span class="sectionKicker">RWL ORIGINAL EXPERIENCE</span><h1>${esc(title(d))}</h1>${detailStatsV9(d,type)}<div class="genreChips detailGenres">${genres.map(g=>`<button data-route="genre/${type}/${g.id}">${esc(g.name)}</button>`).join('')}</div><p class="detailOverview">${esc(d.overview||'')}</p><div class="detailActions"><button class="primary detailAction" id="watchNow">${premiumSvg('play')}<span>${tr('شاهد الآن','Watch Now')}</span></button>${hasTrailer?`<button class="secondary detailAction" data-trailer-media="${type}/${id}">${premiumSvg('trailer')}<span>${tr('التريلر','Trailer')}</span></button>`:''}<button class="secondary detailAction" id="favBtn">${premiumSvg('heart')}<span>${isFav?tr('في قائمتي','In My List'):tr('أضف لقائمتي','Add to My List')}</span></button></div></div></div></section><div class="detailBody premiumDetailBody"><section class="detailPanel"><div class="panelTitle"><div><span class="sectionKicker">CAST</span><h2>${tr('طاقم التمثيل','Cast')}</h2></div></div>${castRow(d.credits?.cast)}</section>${seasonUI}<section class="detailPanel sourcePanel"><div class="panelTitle"><div><span class="sectionKicker">PLAYBACK</span><h2>${tr('اختر السيرفر','Choose a server')}</h2></div><div class="sourceStatusBar"><span class="pulse"></span><span id="sourceStatus">${tr('جاري تجهيز السيرفرات…','Preparing servers…')}</span></div></div><div id="directLane"></div><div id="totLane"></div></section>${section(tr('قد يعجبك أيضاً','You may also like'),d.recommendations?.results||d.similar?.results||[])}</div>`;bindDynamic();$('#favBtn').onclick=()=>toggleFav(type,id);if(type==='tv'){await loadEpisodes(id,state.season);$$('[data-season]').forEach(b=>b.onclick=async()=>{state.season=Number(b.dataset.season);state.episode=1;$$('[data-season]').forEach(x=>x.classList.toggle('active',x===b));await loadEpisodes(id,state.season);await loadSources(type,id)})}await loadSources(type,id);$('#watchNow').onclick=()=>{const first=$('.source');if(first)first.click();else toast(tr('لا يوجد سيرفر جاهز الآن','No ready server right now'))}}
async function loadEpisodes(id,season){const d=await api(`/v1/tmdb/season?id=${id}&season=${season}&language=${state.lang==='ar'?'ar-SA':'en-US'}`);const el=$('#episodeList');if(!el)return;el.innerHTML=(d.episodes||[]).map(e=>`<button class="episodeCard ${e.episode_number===state.episode?'active':''}" data-episode="${e.episode_number}">${e.still_path?`<img src="${IMG}w500${e.still_path}" alt="${esc(e.name||'')}">`:`<div class="episodeFallback">${premiumSvg('play')}</div>`}<div class="episodeCopy"><span>${tr('الحلقة','Episode')} ${e.episode_number}</span><b>${esc(e.name||'')}</b><small>${esc(e.air_date||'')}</small><p>${esc(e.overview||'')}</p></div><span class="episodePlay">${premiumSvg('play')}</span></button>`).join('');$$('[data-episode]').forEach(x=>x.onclick=async()=>{state.episode=Number(x.dataset.episode);$$('[data-episode]').forEach(y=>y.classList.toggle('active',y===x));await loadSources('tv',id)})}
function sourceButton(s,i){const q=(s.qualities||[]).map(x=>x.label).filter(Boolean),best=q.sort((a,b)=>(parseInt(b)||0)-(parseInt(a)||0))[0]||'AUTO',tot=s.lane==='p2p';return `<button class="source premiumSource" data-i="${i}"><span class="serverOrdinal">${String(i+1).padStart(2,'0')}</span><span class="serverGlyph">${premiumSvg(tot?'cloud':'bolt')}</span><span class="serverCopy"><b>Server ${i+1}</b><small>${tot?'RWL TOT':'RWL DIRECT'}</small></span><span class="serverQuality">${esc(best)}</span><span class="serverReady"><i></i>${tr('جاهز','Ready')}</span></button>`}
async function loadSources(type,id){const st=$('#sourceStatus');if(st)st.textContent=tr('جاري تجهيز أفضل السيرفرات…','Preparing the best servers…');let data=await api(`/v1/web/sources?${idsQuery(type,id)}`).catch(()=>({servers:[]}));let servers=data.servers||[];const cfg=jget('rwlDebrid',{});if(setting('tot',true)&&cfg?.key&&cfg?.provider){try{const t=await api(`/v1/web/torrents?${idsQuery(type,id)}`);for(const tor of (t.torrents||[]).slice(0,30)){const r=await api('/v1/web/debrid/resolve',{method:'POST',body:JSON.stringify({provider:cfg.provider,key:cfg.key,magnet:tor.magnet,filename:tor.filename,fileIndex:tor.fileIndex,season:state.season,episode:state.episode,cachedOnly:true})}).catch(()=>null);if(r?.ok&&r.url)servers.push({id:`user-${servers.length+1}`,label:`Server ${servers.length+1}`,lane:'p2p',url:r.url,qualities:[]});if(servers.length>=80)break}}catch{}}
 const seen=new Set();servers=servers.filter(s=>s?.url&&!seen.has(s.url)&&seen.add(s.url));const score=s=>{const q=(s.qualities||[]).map(x=>parseInt(x.label)||0);return Math.max(0,...q)+(s.lane==='p2p'?0:20)};servers.sort((a,b)=>score(b)-score(a));if(!setting('direct',true))servers=servers.filter(s=>s.lane==='p2p');if(!setting('tot',true))servers=servers.filter(s=>s.lane!=='p2p');servers=servers.slice(0,80);state.servers=servers;const direct=servers.filter(s=>s.lane!=='p2p'),tot=servers.filter(s=>s.lane==='p2p');if($('#directLane'))$('#directLane').innerHTML=direct.length?`<div class="laneHeader"><div><span class="laneIcon">${premiumSvg('bolt')}</span><div><h3>RWL DIRECT</h3><small>${tr('مصادر تشغيل مباشرة','Direct streaming sources')}</small></div></div><span>${direct.length}</span></div><div class="sources premiumSources">${direct.map((s,i)=>sourceButton(s,i)).join('')}</div>`:'';if($('#totLane'))$('#totLane').innerHTML=tot.length?`<div class="laneHeader"><div><span class="laneIcon">${premiumSvg('cloud')}</span><div><h3>RWL TOT</h3><small>${tr('مصادر سحابية وتورنت','Cloud & torrent sources')}</small></div></div><span>${tot.length}</span></div><div class="sources premiumSources">${tot.map((s,i)=>sourceButton(s,direct.length+i)).join('')}</div>`:'';if(st)st.textContent=servers.length?`${servers.length} ${tr('سيرفر جاهز','servers ready')}`:tr('لا توجد مصادر متاحة حالياً','No sources are available right now');$$('.source').forEach(b=>b.onclick=()=>playServer(servers[Number(b.dataset.i)],Number(b.dataset.i)+1,type,id))}
async function mangaPage(){state.page='manga';dock();setTop(tr('مانجا','Manga'));$('#view').innerHTML=`<div class="page libraryPremium"><div class="libraryHero mangaHero"><span class="sectionKicker">MANGA</span><h1>${tr('قارئ مانجا داخل RWL','Your manga shelf, built in')}</h1><p>${tr('ابحث، افتح الفصول واقرأ بدون مغادرة الموقع.','Search, open chapters and read without leaving RWL.')}</p><div class="searchBox inlineSearch"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/></svg><input id="mangaSearch" class="searchInput" placeholder="${tr('ابحث عن مانجا…','Search manga…')}"></div></div><div id="mangaGrid" class="mediaGrid premiumMediaGrid mangaGrid"><div class="skeletonGrid">${'<i></i>'.repeat(8)}</div></div></div>`;const load=async q=>{const d=await api(`/v1/web/manga?mode=search&query=${encodeURIComponent(q||'')}`).catch(()=>({items:[]}));$('#mangaGrid').innerHTML=(d.items||[]).map(x=>`<article class="posterCard premiumCard mangaCard" data-route="manga-details/${x.id}">${x.cover?`<img class="mangaCardImg" src="${esc(x.cover)}" loading="lazy" alt="${esc(x.title)}">`:'<div class="posterFallback">MANGA</div>'}<div class="posterShade"></div><div class="posterCopy"><b>${esc(x.title)}</b><small>${esc((x.tags||[]).slice(0,2).join(' • '))}</small></div><button class="posterPlay">${premiumSvg('chev')}</button></article>`).join('')||`<div class="empty premiumEmpty">${tr('تعذر تحميل المانجا الآن','Manga is unavailable right now')}</div>`;bindDynamic()};await load('');let tm;$('#mangaSearch').oninput=e=>{clearTimeout(tm);tm=setTimeout(()=>load(e.target.value),350)}}
async function mangaDetails(id){state.page='manga';dock();const [d,ch]=await Promise.all([api(`/v1/web/manga?mode=details&id=${encodeURIComponent(id)}`),api(`/v1/web/manga?mode=chapters&id=${encodeURIComponent(id)}`)]);const m=d.item||{},chapters=(ch.chapters||[]).sort((a,b)=>{const al=a.language==='ar'?0:a.language==='en'?1:2,bl=b.language==='ar'?0:b.language==='en'?1:2;return al-bl||Number(b.chapter||0)-Number(a.chapter||0)});$('#view').innerHTML=`<div class="page mangaDetail premiumReaderHome"><section class="bookHero premiumBookHero">${m.cover?`<img src="${esc(m.cover)}" alt="${esc(m.title||'Manga')}">`:''}<div><span class="sectionKicker">MANGA SERIES</span><h1>${esc(m.title||'Manga')}</h1><p>${esc(m.description||'')}</p><div class="chips">${(m.tags||[]).slice(0,10).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></section><section class="detailPanel"><div class="panelTitle"><div><span class="sectionKicker">CHAPTERS</span><h2>${tr('الفصول','Chapters')}</h2></div><span>${chapters.length}</span></div><div class="chapterList premiumChapters">${chapters.map(x=>`<button data-route="manga-reader/${x.id}"><span class="chapterNumber">${esc(x.chapter||'?')}</span><span><b>${tr('الفصل','Chapter')} ${esc(x.chapter||'?')} ${esc(x.title||'')}</b><small>${esc(x.language||'')} ${x.pages?`• ${x.pages} pages`:''}</small></span>${premiumSvg('chev')}</button>`).join('')||`<div class="empty">${tr('لا توجد فصول متاحة','No chapters available')}</div>`}</div></section></div>`;bindDynamic()}
function settings(){const cfg=jget('rwlDebrid',{provider:'torbox',key:''}),sync=jget('rwlSync',{}),theme=localStorage.getItem('rwlThemeV9')||'cinema';$('#settingsContent').innerHTML=`<div class="settingsIntro"><span class="sectionKicker">RWL CONTROL CENTER</span><h3>${tr('خل التجربة على ذوقك','Make RWL feel yours')}</h3><p>${tr('كل الإعدادات المهمة بدون معلومات تقنية مزعجة.','Everything that matters, without technical clutter.')}</p></div>
<section class="settingsGroup premiumSettings"><div class="settingsGroupTitle"><span class="settingIcon">${svgIcon('palette')}</span><div><h3>${tr('المظهر','Appearance')}</h3><small>${tr('الثيم واللغة والشفافية','Theme, language and glass')}</small></div></div><div class="settingRow"><div><b>${tr('اللغة','Language')}</b><small>${tr('واجهة عربية أو إنجليزية','Arabic or English interface')}</small></div><div class="segmented"><button data-lang="ar" class="${state.lang==='ar'?'active':''}">العربية</button><button data-lang="en" class="${state.lang==='en'?'active':''}">English</button></div></div><div class="themePresetGrid">${Object.entries(themePresetsV9).map(([k,v])=>`<button class="themePreset ${theme===k?'active':''}" data-theme-v9="${k}" style="--swatch:${v.primary};--swatch2:${v.accent};--swatchbg:${v.bg}"><i></i><span>${state.lang==='ar'?v.nameAr:v.nameEn}</span></button>`).join('')}</div>${toggleRow('glassToggle',tr('Liquid Glass','Liquid Glass'),setting('glass',true))}</section>
<section class="settingsGroup premiumSettings"><div class="settingsGroupTitle"><span class="settingIcon">${svgIcon('sliders')}</span><div><h3>${tr('المشغل','Playback')}</h3><small>${tr('تحكم في تجربة المشاهدة','Tune your viewing experience')}</small></div></div><div class="settingRow"><div><b>${tr('السرعة الافتراضية','Default speed')}</b><small>${tr('يمكن تغييرها من المشغل أيضاً','Also adjustable in player')}</small></div><select id="defaultSpeed">${[.5,.75,1,1.25,1.5,1.75,2].map(x=>`<option value="${x}">${x}×</option>`).join('')}</select></div>${toggleRow('skipToggle',tr('تخطي المقدمة والنهاية','Skip intro & credits'),setting('skip',true))}${toggleRow('failoverToggle',tr('انتقال تلقائي لسيرفر آخر','Auto switch failed server'),setting('failover',true))}${toggleRow('directToggle','RWL DIRECT',setting('direct',true))}${toggleRow('totToggle','RWL TOT',setting('tot',true))}</section>
<section class="settingsGroup premiumSettings"><div class="settingsGroupTitle"><span class="settingIcon">${premiumSvg('language')}</span><div><h3>${tr('الترجمة والصوت','Subtitles & Audio')}</h3><small>${tr('اختيارات اللغة والمظهر','Language and presentation')}</small></div></div><div class="settingRow"><div><b>${tr('لغة الترجمة المفضلة','Preferred subtitle')}</b></div><select id="subtitleLang"><option value="ar">العربية</option><option value="en">English</option><option value="off">${tr('بدون تلقائي','No auto selection')}</option></select></div><div class="settingRow"><div><b>${tr('نمط الترجمة','Subtitle style')}</b></div><select id="subtitleStyle"><option value="classic">${tr('نظيف','Clean')}</option><option value="large">${tr('كبير','Large')}</option><option value="yellow">${tr('سينمائي','Cinema')}</option></select></div></section>
<section class="settingsGroup premiumSettings"><div class="settingsGroupTitle"><span class="settingIcon">${premiumSvg('cloud')}</span><div><h3>${tr('الخدمات السحابية','Cloud Services')}</h3><small>${tr('اختياري — لإضافة مصادر RWL TOT','Optional — adds RWL TOT sources')}</small></div></div><div class="settingRow"><div><b>${tr('الخدمة','Service')}</b></div><select id="debridProvider"><option value="torbox">TorBox</option><option value="realdebrid">Real-Debrid</option><option value="alldebrid">AllDebrid</option><option value="premiumize">Premiumize</option><option value="debridlink">Debrid-Link</option></select></div><div class="settingRow secretRow"><div><b>API Key</b><small>${tr('محفوظ على هذا الجهاز فقط','Stored on this device only')}</small></div><input id="debridKey" type="password" value="${esc(cfg.key||'')}" autocomplete="off" placeholder="••••••••••••"></div><div class="settingRow"><button id="saveDebrid" class="primary wideAction">${tr('حفظ الربط','Save connection')}</button></div></section>
<section class="settingsGroup premiumSettings"><div class="settingsGroupTitle"><span class="settingIcon">${svgIcon('heart')}</span><div><h3>${tr('المزامنة','Sync')}</h3><small>Trakt / Simkl</small></div></div><div class="syncGrid"><label><span>Trakt Client ID</span><input id="traktClient" value="${esc(sync.traktClient||'')}"></label><label><span>Trakt Token</span><input id="traktToken" type="password" value="${esc(sync.traktToken||'')}"></label><label><span>Simkl Client ID</span><input id="simklClient" value="${esc(sync.simklClient||'')}"></label><label><span>Simkl Token</span><input id="simklToken" type="password" value="${esc(sync.simklToken||'')}"></label></div><div class="settingActionRow"><button id="saveSync" class="secondary">${tr('حفظ','Save')}</button><button id="pullTrakt" class="secondary">Trakt Sync</button><button id="pullSimkl" class="secondary">Simkl Sync</button></div></section>
<section class="settingsGroup premiumSettings"><div class="settingsGroupTitle"><span class="settingIcon">${svgIcon('download')}</span><div><h3>${tr('البيانات','Data')}</h3><small>${tr('نسخة احتياطية واستعادة','Backup and restore')}</small></div></div><div class="settingActionRow"><button id="exportCfg" class="secondary">${tr('تصدير نسخة','Export')}</button><label class="secondary fileBtn">${tr('استعادة نسخة','Restore')}<input id="importCfg" type="file" accept="application/json" hidden></label><button id="clearData" class="dangerGhost">${tr('مسح البيانات','Clear')}</button></div></section>`;
 $('#defaultSpeed').value=localStorage.getItem('rwlDefaultSpeed')||'1';$('#debridProvider').value=cfg.provider||'torbox';$('#subtitleStyle').value=localStorage.getItem('rwlSubtitleStyle')||'classic';$('#subtitleLang').value=localStorage.getItem('rwlSubtitleLang')||'ar';$$('[data-lang]').forEach(b=>b.onclick=()=>{localStorage.setItem('rwlLang',b.dataset.lang);state.lang=b.dataset.lang;location.reload()});$$('[data-theme-v9]').forEach(b=>b.onclick=()=>{applyTheme(b.dataset.themeV9);$$('[data-theme-v9]').forEach(x=>x.classList.toggle('active',x===b))});$('#glassToggle').onchange=e=>{setSetting('glass',e.target.checked);document.body.classList.toggle('noGlass',!e.target.checked)};$('#skipToggle').onchange=e=>setSetting('skip',e.target.checked);$('#failoverToggle').onchange=e=>setSetting('failover',e.target.checked);$('#directToggle').onchange=e=>setSetting('direct',e.target.checked);$('#totToggle').onchange=e=>setSetting('tot',e.target.checked);$('#defaultSpeed').onchange=e=>localStorage.setItem('rwlDefaultSpeed',e.target.value);$('#subtitleStyle').onchange=e=>{localStorage.setItem('rwlSubtitleStyle',e.target.value);applySubtitleStyle()};$('#subtitleLang').onchange=e=>localStorage.setItem('rwlSubtitleLang',e.target.value);$('#saveDebrid').onclick=()=>{jset('rwlDebrid',{provider:$('#debridProvider').value,key:$('#debridKey').value.trim()});toast(tr('تم الحفظ','Saved'))};$('#saveSync').onclick=()=>{jset('rwlSync',{traktClient:$('#traktClient').value.trim(),traktToken:$('#traktToken').value.trim(),simklClient:$('#simklClient').value.trim(),simklToken:$('#simklToken').value.trim()});toast(tr('تم الحفظ','Saved'))};$('#pullTrakt').onclick=async()=>{$('#saveSync').click();await pullSync('trakt')};$('#pullSimkl').onclick=async()=>{$('#saveSync').click();await pullSync('simkl')};$('#exportCfg').onclick=()=>{const keys=['rwlLang','rwlThemeV9','rwlPrefs','rwlDebrid','rwlSync','rwlFavs','rwlContinue','rwlIptvChannels','rwlBooks','rwlSubtitleStyle','rwlSubtitleLang','rwlSubOffset','rwlDefaultSpeed'];const obj={version:RWL_WEB_VERSION};for(const k of keys)obj[k]=localStorage.getItem(k);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download='RWL-Movies-v9-backup.json';a.click()};$('#importCfg').onchange=async e=>{try{const o=JSON.parse(await e.target.files[0].text());for(const[k,v]of Object.entries(o))if(k!=='version'&&typeof v==='string')localStorage.setItem(k,v);location.reload()}catch{toast(tr('ملف غير صالح','Invalid file'))}};$('#clearData').onclick=()=>{if(confirm(tr('مسح بيانات RWL المحلية؟','Clear local RWL data?'))){localStorage.clear();location.reload()}};open('settingsOverlay')}
function renderSubtitleSheet(filter=''){const list=$('#subtitleLanguageList');if(!list)return;const groups=new Map();state.subtitles.forEach((s,i)=>{const c=langCode(s);if(!groups.has(c))groups.set(c,[]);groups.get(c).push({s,i})});const pref=['ar','en'];const keys=[...groups.keys()].sort((a,b)=>{const ai=pref.indexOf(a),bi=pref.indexOf(b);if(ai>=0||bi>=0)return(ai<0?99:ai)-(bi<0?99:bi);return a.localeCompare(b)});const q=String(filter||'').trim().toLowerCase();let html=`<button class="subtitleOff ${state._activeSubtitle==null?'active':''}" data-sub-off><span class="subOffIcon">×</span><span><b>${tr('إيقاف الترجمة','Subtitles Off')}</b><small>${tr('تشغيل الفيديو بدون ترجمة','Play without captions')}</small></span></button>`;for(const code of keys){const info=LANG_INFO[code]||['🌐',code.toUpperCase(),code.toUpperCase()],name=state.lang==='ar'?info[1]:info[2];if(q&&!name.toLowerCase().includes(q)&&!code.includes(q))continue;const arr=groups.get(code);html+=`<div class="languageGroup ${['ar','en'].includes(code)?'open':''}" data-lang-group="${code}"><div class="languageHead"><strong><span class="langFlag">${info[0]}</span><span>${esc(name)}</span></strong><span class="langCount">${arr.length}</span></div><div class="languageTracks">${arr.map(({s,i},n)=>`<button class="subTrack ${state._activeSubtitle===i?'active':''}" data-sub-index="${i}"><span><b>${esc(s.name||s.label||`${name} ${n+1}`)}</b><small>${tr('نسخة ترجمة','Subtitle track')} ${String(n+1).padStart(2,'0')}</small></span><span class="subSelectMark">${state._activeSubtitle===i?'✓':'›'}</span></button>`).join('')}</div></div>`}list.innerHTML=html;$$('.languageHead').forEach(h=>h.onclick=()=>h.parentElement.classList.toggle('open'));$$('[data-sub-index]').forEach(b=>b.onclick=async()=>{await setSubtitle(Number(b.dataset.subIndex));renderSubtitleSheet($('#subtitleSearch').value);close('subtitleOverlay')});$('[data-sub-off]')?.addEventListener('click',async()=>{await setSubtitle('off');renderSubtitleSheet();close('subtitleOverlay')})}
function playerMenu(type){const m=$('#floatingMenu');m.innerHTML='';m.className='floatingMenuV9';const titleMap={speed:tr('سرعة التشغيل','Playback speed'),quality:tr('الجودة','Quality'),audio:tr('الصوت','Audio'),substyle:tr('مظهر الترجمة','Subtitle style')};m.insertAdjacentHTML('beforeend',`<div class="menuTitle"><b>${titleMap[type]||'RWL'}</b><button onclick="this.parentElement.parentElement.classList.remove('open')">×</button></div>`);const add=(label,fn,active=false,sub='')=>{const b=document.createElement('button');b.className='menuOption'+(active?' active':'');b.innerHTML=`<span><b>${esc(label)}</b>${sub?`<small>${esc(sub)}</small>`:''}</span><i>${active?'✓':'›'}</i>`;b.onclick=()=>{fn();m.classList.remove('open');showPlayerControls()};m.appendChild(b)};if(type==='speed'){[.5,.75,1,1.25,1.5,1.75,2].forEach(x=>add(`${x}×`,()=>{$('#webPlayer').playbackRate=x;$('#speedBtn').textContent=`${x}×`;localStorage.setItem('rwlDefaultSpeed',String(x))},Math.abs($('#webPlayer').playbackRate-x)<.01,x===1?tr('عادي','Normal'):x===2?tr('سريع','Fast'):''))}else if(type==='quality'){add('AUTO',()=>switchQuality(''),!(state.activeServer?.qualities||[]).length,tr('أفضل جودة متاحة','Best available'));for(const q of(state.activeServer?.qualities||[]))add(q.label||'Quality',()=>switchQuality(q.url),false)}else if(type==='audio'){const tracks=$('#webPlayer').audioTracks;if(tracks&&tracks.length){for(let i=0;i<tracks.length;i++)add(tracks[i].label||tracks[i].language||`Audio ${i+1}`,()=>{for(let j=0;j<tracks.length;j++)tracks[j].enabled=j===i},tracks[i].enabled)}else add(tr('المسار الافتراضي','Default audio'),()=>{},true,tr('يعتمد على المصدر','Provided by the source'))}else if(type==='substyle'){[['classic',tr('نظيف','Clean')],['large',tr('كبير','Large')],['yellow',tr('سينمائي','Cinema')]].forEach(([k,n])=>add(n,()=>{localStorage.setItem('rwlSubtitleStyle',k);applySubtitleStyle()},localStorage.getItem('rwlSubtitleStyle')===k))}m.classList.toggle('open');showPlayerControls()}
function decorateV9(){document.body.classList.add('rwl-v9');const bs=$('#brandSub');if(bs)bs.textContent='Premium';const ss=$('#settingsSubtitle');if(ss)ss.textContent=tr('إعدادات التجربة','Experience settings');applyTheme();}
decorateV9();
init();
async function discover(type='all'){
  state.page='discover';dock();setTop(tr('استكشاف','Discover'));
  if(type==='person'){
    const d=await api(`/v1/tmdb/people?language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({results:[]}));
    $('#view').innerHTML=`<div class="page browsePage"><div class="pageHeroTitle"><span class="sectionKicker">PEOPLE</span><h1>${tr('نجوم وأسماء تستحق المتابعة','Stars worth following')}</h1><p>${tr('اضغط على أي ممثل لعرض أعماله السينمائية والتلفزيونية.','Open any profile to explore their movies and TV work.')}</p></div><div class="personGrid premiumPeople peopleBrowse">${(d.results||[]).slice(0,60).map(p=>`<button class="personCard bare" data-person="${p.id}">${p.profile_path?`<img src="${IMG}w342${p.profile_path}" alt="${esc(p.name)}">`:`<span class="castFallback">${esc((p.name||'?')[0])}</span>`}<b>${esc(p.name)}</b><small>${esc((p.known_for||[]).slice(0,2).map(title).filter(Boolean).join(' · '))}</small></button>`).join('')}</div></div>`;bindDynamic();return;
  }
  const mode=['movie','tv'].includes(type)?type:'all';
  const [d,genres]=await Promise.all([api(`/v1/tmdb/trending?type=${mode}&window=week&language=${state.lang==='ar'?'ar-SA':'en-US'}`),api(`/v1/tmdb/genres?type=movie&language=${state.lang==='ar'?'ar-SA':'en-US'}`).catch(()=>({genres:[]}))]);
  $('#view').innerHTML=`<div class="page browsePage"><div class="pageHeroTitle"><span class="sectionKicker">DISCOVER</span><h1>${tr('اختَر ما يناسب مزاجك','Find your next obsession')}</h1><p>${tr('تصفح الأفلام والمسلسلات والتصنيفات بدون ضوضاء.','Browse movies, TV and genres with a clean cinematic layout.')}</p></div><div class="browseTabs"><button class="${mode==='all'?'active':''}" data-route="discover/all">${tr('الكل','All')}</button><button class="${mode==='movie'?'active':''}" data-route="discover/movie">${tr('أفلام','Movies')}</button><button class="${mode==='tv'?'active':''}" data-route="discover/tv">${tr('مسلسلات','TV')}</button><button data-route="discover/person">${tr('ممثلون','People')}</button></div><div class="genreChips">${(genres.genres||[]).slice(0,14).map(g=>`<button data-route="genre/movie/${g.id}">${esc(g.name)}</button>`).join('')}</div><div class="mediaGrid premiumMediaGrid">${row(d.results)}</div></div>`;bindDynamic();
}
